(window.SB_FULLC=window.SB_FULLC||{})["py"]={c:"[{\"w\":\"pyrite\",\"d\":\"a common mineral (iron disulfide) that has a pale yellow color\",\"s\":\"The young geologist was excited until her teacher explained that the shiny golden mineral was just pyrite, not real gold.\",\"p\":\"PEYE-reyet\",\"o\":\"Greek\",\"y\":7,\"bp\":29,\"m\":\"pyright\",\"sy\":\"pay.ray.t\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"minerals\",\"colors\",\"ogreek\"]},{\"w\":\"pyrotechnics\",\"d\":\"(music) brilliance of display (as in the performance of music)\",\"s\":\"The pianist's pyrotechnics during the final movement left the audience breathless and on their feet.\",\"p\":\"peye-roh-TEH-nihks\",\"o\":\"Latin\",\"y\":8,\"bp\":37,\"m\":\"pyrotechnicks\",\"sy\":\"py.ro.tech.nics\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"music\",\"colors\",\"olatin\"]},{\"w\":\"pyramid\",\"d\":\"a polyhedron having a polygonal base and triangular sides with a common vertex\",\"s\":\"Our class built a cardboard pyramid as part of our project on ancient Egyptian architecture.\",\"p\":\"PIH-ruh-mihd\",\"o\":\"French\",\"y\":4,\"bp\":31,\"m\":\"pyramd\",\"sy\":\"pih.rah.mih.d\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"numbers\",\"ofrench\"]},{\"w\":\"Pythagorean\",\"d\":\"of or relating to Pythagoras or his geometry\",\"s\":\"Using the Pythagorean theorem, Maria calculated the length of the longest side of the right triangle.\",\"p\":\"pih-thuh-GAW-ree-uhn\",\"o\":\"Latin\",\"y\":7,\"bp\":71,\"sy\":\"py.thag.o.re.an\",\"nt\":\"Senior\",\"ps\":\"adjective\",\"t\":[\"numbers\",\"eponyms\",\"olatin\",\"eplatin\"]},{\"w\":\"pylorus\",\"d\":\"a small circular opening between the stomach and the duodenum\",\"s\":\"The biology teacher explained that the pylorus acts as a gatekeeper, releasing partially digested food from the stomach into the small intestine.\",\"p\":\"py-LOR-us\",\"o\":\"Greek\",\"y\":7,\"bp\":65,\"m\":\"pylerous\",\"sy\":\"py.lo.rus\",\"nt\":\"Senior\",\"ps\":\"noun\",\"t\":[\"body\",\"ogreek\"]},{\"w\":\"pyre\",\"d\":\"wood heaped for burning a dead body as a funeral rite\",\"s\":\"At the Viking funeral in the film, the warriors lit the pyre and watched the flames rise toward the sky.\",\"p\":\"PEYE-er\",\"o\":\"Latin\",\"y\":7,\"bp\":27,\"m\":\"pier\",\"sy\":\"pay.er\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"pygmy\",\"d\":\"a kind of animal or plant that is much smaller than the usual kind\",\"s\":\"The pygmy seahorse is so tiny it can easily hide among the coral branches of a reef.\",\"p\":\"PIH-gmee\",\"o\":\"Greek\",\"y\":5,\"bp\":28,\"m\":\"pigmy\",\"sy\":\"pih.gmiy\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pylon\",\"d\":\"a tower for guiding pilots or marking the turning point in a race\",\"s\":\"Power pylons are a favorite target for terrorists.\",\"p\":\"PEYE-lahn\",\"o\":\"Greek\",\"y\":5,\"bp\":28,\"m\":\"pilon\",\"sy\":\"pay.laa.n\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"buildings\",\"sports\",\"ogreek\"]},{\"w\":\"pylons\",\"d\":\"a tower for guiding pilots or marking the turning point in a race\",\"s\":\"Tall electricity pylons marched across the fields toward the town.\",\"p\":\"PEYE-lahnz\",\"o\":\"Greek\",\"y\":6,\"bp\":29,\"m\":\"pilons\",\"sy\":\"pay.laa.nz\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"buildings\",\"sports\",\"ogreek\"]},{\"w\":\"pylori\",\"d\":\"a small circular opening between the stomach and the duodenum\",\"s\":\"The doctor explained that the bacteria Helicobacter pylori can cause painful stomach ulcers.\",\"p\":\"peye-LAW-ree\",\"o\":\"Greek\",\"y\":7,\"bp\":30,\"m\":\"pilori\",\"sy\":\"pay.lao.riy\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"body\",\"ogreek\"]},{\"w\":\"pyres\",\"d\":\"wood heaped for burning a dead body as a funeral rite\",\"s\":\"Huge pyres burned on the hillside as part of the ancient funeral ceremony for fallen warriors.\",\"p\":\"PEYE-erz\",\"o\":\"Greek\",\"y\":7,\"bp\":28,\"m\":\"pires\",\"sy\":\"pay.er.z\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pythia\",\"d\":\"(Greek mythology) the priestess of Apollo at Delphi who transmitted the oracles\",\"s\":\"The Pythia sat above the sacred crack in the earth and delivered her mysterious prophecies.\",\"p\":\"PIH-thee-uh\",\"o\":\"Greek\",\"y\":8,\"bp\":30,\"m\":\"pythea\",\"sy\":\"pih.thiy.ah\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"myth\",\"religion\",\"ogreek\"]},{\"w\":\"python\",\"d\":\"large Old World boas\",\"s\":\"The enormous python slowly coiled around the branch and waited patiently for its prey.\",\"p\":\"PEYE-thahn\",\"o\":\"Greek\",\"y\":4,\"bp\":29,\"m\":\"phython\",\"sy\":\"pay.thaa.n\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"eponyms\",\"ogreek\",\"epgreek\"]},{\"w\":\"pyxis\",\"d\":\"fruit of such plants as the plantain; a capsule whose upper part falls off when the seeds are released\",\"s\":\"The botanist pointed out the pyxis of the plantain, explaining how its lid pops off to release seeds.\",\"p\":\"PIH-ksihs\",\"o\":\"Latin\",\"y\":5,\"bp\":28,\"m\":\"pixis\",\"sy\":\"pih.ksih.s\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"botany\",\"spices\",\"olatin\"]},{\"w\":\"pygmalion\",\"d\":\"(Greek mythology) a king who created a statue of a woman and fell in love with it; Aphrodite brought the sculpture to life as Galatea\",\"s\":\"The drama teacher compared the strict professor to Pygmalion because he tried to completely transform his student's speech and manner.\",\"p\":\"pih-GMAY-lyuhn\",\"o\":\"Greek\",\"y\":7,\"bp\":33,\"m\":\"pigmalion\",\"sy\":\"pih.gmey.lyah.n\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"myth\",\"royalty\",\"sculpture\",\"ogreek\"]},{\"w\":\"pygmies\",\"d\":\"animals or plants that are much smaller than others of their kind\",\"s\":\"The pygmies of the owl family are barely bigger than a sparrow.\",\"p\":\"PIH-gmeez\",\"o\":\"Greek\",\"y\":6,\"bp\":30,\"m\":\"pigmies\",\"sy\":\"pih.gmiy.z\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyongyang\",\"d\":\"capital of North Korea and an industrial center\",\"s\":\"Pyongyang is Korea's oldest city but little of its history has been preserved.\",\"p\":\"pyaw-NGYANG\",\"o\":\"Korean\",\"y\":4,\"bp\":27,\"sy\":\"pyao.ngyae.ng\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"nations\",\"oeastasia\"]},{\"w\":\"pyramidal\",\"d\":\"resembling a pyramid\",\"s\":\"The architect designed a striking pyramidal roof that narrowed to a sharp point against the sky.\",\"p\":\"per-A-muh-duhl\",\"o\":\"Greek\",\"y\":6,\"bp\":34,\"m\":\"pyramidel\",\"sy\":\"per.ae.mah.dah.l\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"ancient\",\"ogreek\"]},{\"w\":\"pyramids\",\"d\":\"a polyhedron having a polygonal base and triangular sides with a common vertex\",\"s\":\"The ancient pyramids of Egypt still stand thousands of years after they were built, astonishing every visitor who sees them.\",\"p\":\"PIH-ruh-mihdz\",\"o\":\"Greek\",\"y\":5,\"bp\":32,\"sy\":\"pih.rah.mih.dz\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"numbers\",\"ogreek\"]},{\"w\":\"pyrenees\",\"d\":\"a chain of mountains between France and Spain\",\"s\":\"Hikers who cross the Pyrenees are rewarded with breathtaking views of snow-capped peaks stretching along the border of France and Spain.\",\"p\":\"PIH-ruh-eez\",\"o\":\"Greek\",\"y\":6,\"bp\":32,\"m\":\"Pyrennees\",\"sy\":\"pih.rah.iy.z\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"landforms\",\"ogreek\"]},{\"w\":\"pyroxene\",\"d\":\"any of a group of crystalline silicate mineral common in igneous and metamorphic rocks\",\"s\":\"The geology student identified a dark green mineral in the volcanic rock sample as pyroxene.\",\"p\":\"peye-RAH-kseen\",\"o\":\"French\",\"y\":8,\"bp\":32,\"m\":\"pyroxine\",\"sy\":\"pay.raa.ksiy.n\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"minerals\",\"ofrench\"]},{\"w\":\"pyrrhic\",\"d\":\"a metrical unit with unstressed-unstressed syllables\",\"p\":\"PIH-rihk\",\"o\":\"Latin\",\"y\":7,\"bp\":30,\"m\":\"pirhic\",\"sy\":\"pih.rih.k\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"wordwords\",\"olatin\"]},{\"w\":\"pyrotechnic\",\"d\":\"(usually plural) a device with an explosive that burns at a low rate and with colored flames; can be used to illuminate areas or send signals etc.\",\"s\":\"The pyrotechnic display at the stadium lit up the entire night sky with bursting red and gold explosions that left the cheering crowd completely breathless and amazed.\",\"p\":\"peye-roh-TEH-knihk\",\"o\":\"Latin\",\"y\":8,\"bp\":36,\"m\":\"pyrotechnic spelled pyrotechnik\",\"sy\":\"pay.row.teh.knih.k\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"tools\",\"colors\",\"olatin\"]},{\"w\":\"pythagoras\",\"d\":\"Greek philosopher and mathematician who proved the Pythagorean theorem; considered to be the first true mathematician (circa 580-500 BC)\",\"s\":\"Pythagoras is so famous for his work with right triangles that math students still use his theorem every day.\",\"p\":\"pih-thuh-GAW-rahs\",\"o\":\"Greek\",\"y\":7,\"bp\":35,\"m\":\"pythagerous\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"logic\",\"numbers\",\"ogreek\"]},{\"w\":\"pya\",\"d\":\"Small coins used in Myanmar; a hundred of them make one kyat.\",\"s\":\"He handed over a few pya to pay for the small piece of fruit at the market.\",\"p\":\"PYAH\",\"y\":8,\"bp\":21,\"m\":\"pia\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"economy\"]},{\"w\":\"pyas\",\"d\":\"Small coins used in Myanmar; a hundred of them make one kyat.\",\"s\":\"The vendor counted out the pyas and slipped them into his worn coin pouch.\",\"p\":\"PYAHZ\",\"y\":7,\"bp\":22,\"m\":\"pias\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"economy\"]},{\"w\":\"pyemia\",\"d\":\"septicemia caused by pus-forming bacteria being released from an abscess\",\"s\":\"The surgeon warned that the untreated wound could lead to dangerous pyemia.\",\"p\":\"py-EE-mee-uh\",\"o\":\"Greek\",\"y\":9,\"bp\":32,\"m\":\"pyaemia\",\"sy\":\"py.e.mi.a\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"disease\",\"ogreek\"]},{\"w\":\"pyemic\",\"d\":\"of or relating to pyemia\",\"s\":\"The doctor noted pyemic symptoms and immediately ordered stronger antibiotics.\",\"p\":\"py-EE-mik\",\"o\":\"Greek\",\"y\":8,\"bp\":30,\"m\":\"pyaemic\",\"sy\":\"py.e.mic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"pyjama\",\"d\":\"a pair of loose trousers tied by a drawstring around the waist; worn by men and women in some Asian countries\",\"s\":\"He slipped on his pyjama bottoms and shuffled sleepily to the kitchen.\",\"p\":\"puh-JAH-muh\",\"o\":\"Hindi\",\"y\":7,\"bp\":26,\"m\":\"pajama\",\"sy\":\"py.ja.ma\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"fabrics\",\"osouth\"]},{\"w\":\"pyknic\",\"d\":\"having a squat and fleshy build\",\"s\":\"The wrestling coach noted that his pyknic athlete had a natural advantage in the sport.\",\"p\":\"PIK-nik\",\"o\":\"Greek\",\"y\":9,\"bp\":29,\"m\":\"piknic\",\"sy\":\"pyk.nic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"pyrene\",\"d\":\"a pale yellow crystalline hydrocarbon C16H10 extracted from coal tar\",\"s\":\"The chemist isolated pyrene crystals from the coal tar sample in the laboratory.\",\"p\":\"PY-reen\",\"o\":\"Greek\",\"y\":8,\"bp\":29,\"m\":\"pyreen\",\"sy\":\"py.rene\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"minerals\",\"ogreek\"]},{\"w\":\"pyrex\",\"d\":\"a borosilicate glass with a low coefficient of expansion; used for heat-resistant glassware in cooking and chemistry\",\"s\":\"She poured the boiling soup into a pyrex dish without worrying about cracking.\",\"p\":\"PY-reks\",\"o\":\"Greek\",\"y\":6,\"bp\":28,\"m\":\"pirex\",\"sy\":\"py.rex\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"culinary\",\"ogreek\"]},{\"w\":\"pyrola\",\"d\":\"A low evergreen woodland plant with rounded leaves and nodding flowers.\",\"s\":\"The botanist discovered a patch of pyrola growing quietly beneath the pine trees.\",\"p\":\"PIR-oh-luh\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"m\":\"pyrolla\",\"sy\":\"py.ro.la\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"botany\",\"flowers\",\"olatin\"]},{\"w\":\"pyrope\",\"d\":\"a deep red garnet used as a gemstone\",\"s\":\"The jeweler set a gleaming pyrope into the center of the antique ring.\",\"p\":\"PY-rohp\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"m\":\"pyrop\",\"sy\":\"py.rope\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"pyrus\",\"d\":\"fruit trees native to the Old World: pears\",\"s\":\"The orchard was planted with several varieties of pyrus, producing an abundance of pears.\",\"p\":\"PY-rus\",\"o\":\"Latin\",\"y\":7,\"bp\":28,\"m\":\"pyrrus\",\"sy\":\"py.rus\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"flowers\",\"spices\",\"olatin\"]},{\"w\":\"pyuria\",\"d\":\"presence of white blood cells in the urine; symptom of urinary tract infection\",\"s\":\"The lab results confirmed pyuria, indicating the patient had a urinary tract infection.\",\"p\":\"py-YOOR-ee-uh\",\"o\":\"Greek\",\"y\":9,\"bp\":32,\"m\":\"pyurea\",\"sy\":\"py.u.ri.a\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"ogreek\"]},{\"w\":\"pyx\",\"d\":\"a chest in which coins from the mint are held to await assay\",\"s\":\"The mint official opened the pyx to retrieve coins for the annual assay ceremony.\",\"p\":\"PIKS\",\"o\":\"Latin\",\"y\":5,\"bp\":25,\"m\":\"pix\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"economy\",\"numismatics\",\"olatin\"]},{\"w\":\"pyxes\",\"d\":\"a chest in which coins from the mint are held to await assay\",\"s\":\"Several pyxes were lined up on the table, each containing coins from a different year.\",\"p\":\"PIK-sez\",\"o\":\"Greek\",\"y\":7,\"bp\":28,\"m\":\"pixes\",\"sy\":\"pyx.es\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"spices\",\"economy\",\"ogreek\"]},{\"w\":\"pyxie\",\"d\":\"creeping evergreen shrub having narrow overlapping leaves and early white star-shaped flowers; of the pine barrens of New Jersey and the Carolinas\",\"s\":\"The naturalist was thrilled to spot a patch of pyxie spreading across the forest floor.\",\"p\":\"PIK-see\",\"o\":\"Greek\",\"y\":8,\"bp\":28,\"m\":\"pixie\",\"sy\":\"pyx.ie\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"botany\",\"flowers\",\"astronomy\",\"ogreek\"]},{\"w\":\"pyxies\",\"d\":\"creeping evergreen shrub having narrow overlapping leaves and early white star-shaped flowers; of the pine barrens of New Jersey and the Carolinas\",\"s\":\"The trail guide pointed out the pyxies blooming with delicate white flowers along the path.\",\"p\":\"PIK-seez\",\"o\":\"Greek\",\"y\":8,\"bp\":29,\"m\":\"pixies\",\"sy\":\"pyx.ies\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"botany\",\"flowers\",\"astronomy\",\"ogreek\"]},{\"w\":\"pyaemia\",\"d\":\"septicemia caused by pus-forming bacteria being released from an abscess\",\"s\":\"Before the era of antibiotics, pyaemia was a frequently fatal complication of infected wounds.\",\"p\":\"py-EE-mee-uh\",\"o\":\"Greek\",\"y\":9,\"bp\":33,\"m\":\"pyemia\",\"sy\":\"py.ae.mi.a\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"disease\",\"ogreek\"]},{\"w\":\"pyaemias\",\"d\":\"septicemia caused by pus-forming bacteria being released from an abscess\",\"s\":\"Historical medical records documented numerous pyaemias among soldiers wounded in battle.\",\"p\":\"py-EE-mee-uhz\",\"o\":\"Greek\",\"y\":8,\"bp\":33,\"m\":\"pyemias\",\"sy\":\"py.ae.mi.as\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"disease\",\"ogreek\"]},{\"w\":\"pyaemic\",\"d\":\"of or relating to pyemia\",\"s\":\"The doctor recognized the pyaemic symptoms and immediately began aggressive treatment.\",\"p\":\"py-EE-mik\",\"o\":\"Greek\",\"y\":8,\"bp\":31,\"m\":\"pyemic\",\"sy\":\"py.ae.mic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"pycnidia\",\"d\":\"flask-shaped asexual structure containing conidia\",\"s\":\"Under the microscope, the plant pathologist identified the tiny pycnidia embedded in the infected leaf tissue.\",\"p\":\"pik-NID-ee-uh\",\"o\":\"Greek\",\"y\":9,\"bp\":33,\"m\":\"pycnidhia\",\"sy\":\"pyc.nid.i.a\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pycnidium\",\"d\":\"flask-shaped asexual structure containing conidia\",\"s\":\"Each pycnidium releases thousands of spores that can infect neighboring plants.\",\"p\":\"pik-NID-ee-um\",\"o\":\"Greek\",\"y\":9,\"bp\":34,\"m\":\"pycnideum\",\"sy\":\"pyc.nid.i.um\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pycnosis\",\"d\":\"a degenerative state of the cell nucleus\",\"s\":\"The pathologist noted pycnosis in the tissue sample, indicating that the cells were dying.\",\"p\":\"pik-NOH-sis\",\"o\":\"Greek\",\"y\":9,\"bp\":32,\"m\":\"pyknosis\",\"sy\":\"pyc.no.sis\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pycnotic\",\"d\":\"of or relating to or exhibiting pyknosis\",\"s\":\"The slide showed several pycnotic nuclei, confirming that cell death had occurred in that region.\",\"p\":\"pik-NOT-ik\",\"o\":\"Greek\",\"y\":9,\"bp\":32,\"m\":\"pyknotic\",\"sy\":\"pyc.not.ic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"pyelitis\",\"d\":\"inflammation of the renal pelvis\",\"s\":\"The patient was diagnosed with pyelitis after complaining of persistent back pain and fever.\",\"p\":\"py-uh-LY-tis\",\"o\":\"Greek\",\"y\":8,\"bp\":33,\"m\":\"pyelitus\",\"sy\":\"py.e.li.tis\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"disease\",\"ogreek\"]},{\"w\":\"pyelogram\",\"d\":\"an X ray of the kidneys and ureters\",\"s\":\"The urologist ordered a pyelogram to check for any blockages in the patient's urinary tract.\",\"p\":\"PY-uh-loh-gram\",\"o\":\"Greek\",\"y\":8,\"bp\":34,\"m\":\"pyelagram\",\"sy\":\"py.e.lo.gram\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"body\",\"ogreek\"]},{\"w\":\"pyemias\",\"d\":\"septicemia caused by pus-forming bacteria being released from an abscess\",\"s\":\"The medical historian wrote about the devastating pyemias that swept through Civil War field hospitals.\",\"p\":\"py-EE-mee-uhz\",\"o\":\"Greek\",\"y\":8,\"bp\":33,\"m\":\"pyaemias\",\"sy\":\"py.e.mi.as\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"disease\",\"ogreek\"]},{\"w\":\"pygopus\",\"d\":\"type genus of the Pygopodidae; snake-shaped pleurodont lizard with no forelimbs and only rudimentary hind limbs\",\"s\":\"The herpetologist spotted a pygopus slithering through the Australian brush, its legless body easy to mistake for a snake.\",\"p\":\"PY-goh-pus\",\"o\":\"Greek\",\"y\":9,\"bp\":31,\"m\":\"pigopus\",\"sy\":\"py.go.pus\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"body\",\"animals\",\"ogreek\"]},{\"w\":\"pyjamas\",\"d\":\"a pair of loose trousers tied by a drawstring around the waist; worn by men and women in some Asian countries\",\"s\":\"He padded downstairs in his striped pyjamas to get a glass of warm milk before bed.\",\"p\":\"puh-JAH-muhz\",\"o\":\"Hindi\",\"y\":3,\"bp\":27,\"m\":\"pajamas\",\"sy\":\"py.ja.mas\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"fabrics\",\"osouth\"]},{\"w\":\"pyknotic\",\"d\":\"of or relating to or exhibiting pyknosis\",\"s\":\"The researcher identified pyknotic cells in the damaged tissue sample under the high-powered microscope.\",\"p\":\"pik-NOT-ik\",\"o\":\"Greek\",\"y\":9,\"bp\":32,\"m\":\"piknotic\",\"sy\":\"pyk.not.ic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"pyloric\",\"d\":\"relating to or near the pylorus\",\"s\":\"The surgeon carefully examined the pyloric valve to ensure food could pass properly from the stomach into the small intestine.\",\"p\":\"py-LOR-ik\",\"o\":\"Greek\",\"y\":7,\"bp\":31,\"m\":\"piloric\",\"sy\":\"py.lor.ic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"pyloruses\",\"d\":\"a small circular opening between the stomach and the duodenum\",\"s\":\"Doctors studying digestive disorders often examine the pyloruses of patients to check for blockages or abnormal narrowing.\",\"p\":\"py-LOR-us-ez\",\"o\":\"Greek\",\"y\":9,\"bp\":34,\"m\":\"piloruses\",\"sy\":\"py.lor.us.es\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"body\",\"ogreek\"]},{\"w\":\"pyocyanin\",\"d\":\"a toxic blue crystalline antibiotic found in green pus\",\"s\":\"The researchers isolated pyocyanin from the bacterial culture, noting its striking blue color and powerful antibiotic properties.\",\"p\":\"py-oh-SY-a-nin\",\"o\":\"Greek\",\"y\":8,\"bp\":36,\"m\":\"pyocyanine\",\"sy\":\"py.o.cy.a.nin\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"pharmacy\",\"chemistry\",\"ogreek\"]},{\"w\":\"pyogenic\",\"d\":\"producing pus\",\"s\":\"The doctor warned that the pyogenic bacteria infecting the wound could cause a dangerous abscess if left untreated.\",\"p\":\"py-oh-JEN-ik\",\"o\":\"Greek\",\"y\":6,\"bp\":33,\"m\":\"piogenic\",\"sy\":\"py.o.gen.ic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"pyorrhea\",\"d\":\"discharge of pus\",\"s\":\"The dentist diagnosed the patient with pyorrhea, a serious gum condition that caused painful swelling and infection.\",\"p\":\"py-oh-REE-ah\",\"o\":\"Greek\",\"y\":9,\"bp\":33,\"m\":\"pyorhea\",\"sy\":\"py.or.rhe.a\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyorrheas\",\"d\":\"discharge of pus\",\"s\":\"The medical textbook described several types of pyorrheas, each affecting different tissues and requiring different treatments.\",\"p\":\"py-oh-REE-ahz\",\"o\":\"Greek\",\"y\":9,\"bp\":34,\"m\":\"pyorheas\",\"sy\":\"py.or.rhe.as\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyorrhoea\",\"d\":\"discharge of pus\",\"s\":\"The British medical journal used the spelling pyorrhoea when describing the gum disease that had affected many patients in the study.\",\"p\":\"py-oh-REE-ah\",\"o\":\"Greek\",\"y\":9,\"bp\":34,\"m\":\"pyorhea\",\"sy\":\"py.or.rhoe.a\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyracanth\",\"d\":\"any of various thorny shrubs of the genus Pyracantha bearing small white flowers followed by hard red or orange-red berries\",\"s\":\"The gardener planted a pyracanth along the fence, admiring its clusters of tiny white flowers and bright red berries in autumn.\",\"p\":\"PY-ra-kanth\",\"o\":\"Greek\",\"y\":9,\"bp\":33,\"m\":\"pyracantha\",\"sy\":\"py.ra.canth\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"botany\",\"flowers\",\"ogreek\"]},{\"w\":\"pyralid\",\"d\":\"usually tropical slender-bodied long-legged moth whose larvae are crop pests\",\"s\":\"The farmer called an exterminator after discovering that a pyralid had laid eggs in his grain storage, threatening the entire harvest.\",\"p\":\"PIR-a-lid\",\"o\":\"Greek\",\"y\":9,\"bp\":31,\"m\":\"piralid\",\"sy\":\"pyr.a.lid\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"insects\",\"farming\",\"ogreek\"]},{\"w\":\"pyralidae\",\"d\":\"bee moths; corn borers; flour moths\",\"s\":\"The entomology professor explained that Pyralidae is a large family of moths that includes many notorious agricultural pests.\",\"p\":\"py-RAL-ih-dee\",\"o\":\"Greek\",\"y\":9,\"bp\":34,\"m\":\"pyralydae\",\"sy\":\"py.ral.i.dae\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"insects\",\"ogreek\"]},{\"w\":\"pyralids\",\"d\":\"usually tropical slender-bodied long-legged moth whose larvae are crop pests\",\"s\":\"The agricultural scientist warned that pyralids were responsible for destroying a significant portion of the corn crop that summer.\",\"p\":\"PIR-a-lidz\",\"o\":\"Greek\",\"y\":9,\"bp\":32,\"m\":\"piralids\",\"sy\":\"pyr.a.lids\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"insects\",\"farming\",\"ogreek\"]},{\"w\":\"pyralis\",\"d\":\"type genus of the Pyralidae\",\"s\":\"The insect collection at the museum featured a preserved specimen of Pyralis, the defining genus of the moth family Pyralidae.\",\"p\":\"PIR-a-lis\",\"o\":\"Greek\",\"y\":9,\"bp\":31,\"m\":\"piralis\",\"sy\":\"pyr.a.lis\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyramided\",\"d\":\"enlarge one's holdings on an exchange on a continued rise by using paper profits as margin to buy additional amounts\",\"s\":\"The ambitious investor pyramided his stock holdings during the bull market, reinvesting each gain to multiply his returns rapidly.\",\"p\":\"PIR-a-mid-ed\",\"o\":\"Greek\",\"y\":9,\"bp\":34,\"m\":\"pyramidded\",\"sy\":\"pyr.a.mid.ed\",\"nt\":\"Open\",\"ps\":\"verb\",\"t\":[\"economy\",\"numbers\",\"ogreek\"]},{\"w\":\"pyramidic\",\"d\":\"resembling a pyramid\",\"s\":\"The architect designed a pyramidic skyscraper that tapered dramatically toward a sharp point at its summit.\",\"p\":\"pir-a-MID-ik\",\"o\":\"Greek\",\"y\":9,\"bp\":34,\"m\":\"pyramidick\",\"sy\":\"pyr.a.mid.ic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"ancient\",\"ogreek\"]},{\"w\":\"pyrausta\",\"d\":\"moths whose larvae are corn borers\",\"s\":\"The agriculture student learned that Pyrausta moths are serious pests because their larvae tunnel into corn stalks and destroy the plants from within.\",\"p\":\"py-RAWS-tah\",\"o\":\"Greek\",\"y\":9,\"bp\":32,\"sy\":\"py.raus.ta\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"insects\",\"ogreek\"]},{\"w\":\"pyrectic\",\"d\":\"any substance that can cause a rise in body temperature\",\"s\":\"The pharmacologist studied how the pyrectic introduced into the test subjects triggered an immediate and measurable rise in body temperature.\",\"p\":\"py-REK-tik\",\"o\":\"Greek\",\"y\":9,\"bp\":32,\"m\":\"pyretic\",\"sy\":\"py.rec.tic\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyrenes\",\"d\":\"a pale yellow crystalline hydrocarbon C16H10 extracted from coal tar\",\"s\":\"The chemistry lab technician carefully extracted pyrenes from the coal tar sample and measured their fluorescence under ultraviolet light.\",\"p\":\"PY-reenz\",\"o\":\"Greek\",\"y\":9,\"bp\":30,\"m\":\"pyreens\",\"sy\":\"py.renes\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"minerals\",\"ogreek\"]},{\"w\":\"pyrethrum\",\"d\":\"An insect-repelling powder made from dried daisy-like flower heads.\",\"s\":\"The organic gardener dusted pyrethrum powder on her roses to repel aphids without using harsh synthetic chemicals.\",\"p\":\"py-REE-thrum\",\"o\":\"Greek\",\"y\":8,\"bp\":33,\"m\":\"pyretheum\",\"sy\":\"py.reth.rum\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"botany\",\"flowers\",\"insects\",\"ogreek\"]},{\"w\":\"pyretic\",\"d\":\"causing fever\",\"s\":\"The nurse noted that the pyretic reaction to the medication was mild but still needed to be monitored closely overnight.\",\"p\":\"py-RET-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":31,\"m\":\"pyritic\",\"sy\":\"py.ret.ic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"pyrexia\",\"d\":\"a rise in the temperature of the body; frequently a symptom of infection\",\"s\":\"The emergency room physician diagnosed the child with pyrexia and immediately ordered blood tests to find the underlying cause of the high fever.\",\"p\":\"py-REK-see-ah\",\"o\":\"Greek\",\"y\":9,\"bp\":33,\"m\":\"pyrexea\",\"sy\":\"py.rex.i.a\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"disease\",\"ogreek\"]},{\"w\":\"pyrexias\",\"d\":\"a rise in the temperature of the body; frequently a symptom of infection\",\"s\":\"The hospital recorded dozens of pyrexias among patients during the flu outbreak, straining the nursing staff with constant temperature monitoring.\",\"p\":\"py-REK-see-ahz\",\"o\":\"Greek\",\"y\":9,\"bp\":33,\"m\":\"pyrexeas\",\"sy\":\"py.rex.i.as\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"disease\",\"ogreek\"]},{\"w\":\"pyridine\",\"d\":\"a toxic colorless flammable liquid organic base with a disagreeable odor; usually derived from coal\",\"s\":\"The chemistry teacher warned students that pyridine, though useful as a solvent, has an unpleasant smell and must be handled only in a well-ventilated lab.\",\"p\":\"PIR-ih-deen\",\"o\":\"Greek\",\"y\":8,\"bp\":32,\"m\":\"pyradine\",\"sy\":\"pyr.i.dine\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"colors\",\"ogreek\"]},{\"w\":\"pyridines\",\"d\":\"a toxic colorless flammable liquid organic base with a disagreeable odor; usually derived from coal\",\"s\":\"The research paper catalogued various pyridines and their potential uses in pharmaceutical development despite their toxic properties.\",\"p\":\"PIR-ih-deenz\",\"o\":\"Greek\",\"y\":8,\"bp\":33,\"m\":\"pyradines\",\"sy\":\"pyr.i.dines\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"colors\",\"ogreek\"]},{\"w\":\"pyridoxal\",\"d\":\"a B vitamin that is essential for metabolism of amino acids and starch\",\"s\":\"The nutritionist explained that pyridoxal, a form of vitamin B6, plays a critical role in helping the body break down proteins and carbohydrates.\",\"p\":\"pir-ih-DOK-sal\",\"o\":\"Greek\",\"y\":7,\"bp\":34,\"m\":\"pyridoxel\",\"sy\":\"pyr.i.dox.al\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"ogreek\"]},{\"w\":\"pyrites\",\"d\":\"any of various metallic-looking sulfides (of which pyrite is the commonest)\",\"s\":\"The young geologist mistook the glittering pyrites in the riverbed for gold, a common error that earned the mineral its nickname fool's gold.\",\"p\":\"PY-ryts\",\"o\":\"Greek\",\"y\":7,\"bp\":30,\"m\":\"pyrittes\",\"sy\":\"py.rites\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyrogen\",\"d\":\"a substance that causes a fever when it gets into the body\",\"s\":\"The laboratory tested each batch of intravenous solution to ensure no pyrogen was present, since even tiny amounts could cause dangerous fever in patients.\",\"p\":\"PY-roh-jen\",\"o\":\"Greek\",\"y\":8,\"bp\":31,\"m\":\"pyrrogen\",\"sy\":\"py.ro.gen\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"ogreek\"]},{\"w\":\"pyrogenic\",\"d\":\"produced by or producing fever\",\"p\":\"py-roh-JEN-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"m\":\"pyrogenicc\",\"sy\":\"py.ro.gen.ic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"disease\",\"olatin\"]},{\"w\":\"pyrogens\",\"d\":\"substances that can cause a fever when they get into the body\",\"s\":\"Hospital pharmacists carefully screen medications for pyrogens, since these fever-inducing substances can pose serious risks to patients receiving injections.\",\"p\":\"PY-roh-jenz\",\"o\":\"Greek\",\"y\":9,\"bp\":32,\"m\":\"pyrrgens\",\"sy\":\"py.ro.gens\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"character\",\"ogreek\"]},{\"w\":\"pyrograph\",\"d\":\"a design produced by pyrography\",\"s\":\"The skilled artist created a detailed pyrograph of a soaring eagle on a smooth pine board, burning every feather with remarkable precision.\",\"p\":\"PY-roh-graf\",\"o\":\"Greek\",\"y\":9,\"bp\":33,\"m\":\"pyrograf\",\"sy\":\"py.ro.graph\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyrolas\",\"d\":\"any of several evergreen perennials of the genus Pyrola\",\"s\":\"The hiker noticed delicate pyrolas growing beneath the pine trees in the shaded forest.\",\"p\":\"PIR-oh-laz\",\"o\":\"Latin\",\"y\":9,\"bp\":31,\"m\":\"pyrollas\",\"sy\":\"pyr.o.las\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"pyrolatry\",\"d\":\"the worship of fire\",\"s\":\"Ancient tribes practiced pyrolatry, believing flames connected them to the gods.\",\"p\":\"py-ROL-uh-tree\",\"o\":\"Latin\",\"y\":9,\"bp\":34,\"m\":\"pyrolotry\",\"sy\":\"py.rol.a.try\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"religion\",\"olatin\"]},{\"w\":\"pyrolysis\",\"d\":\"transformation of a substance produced by the action of heat\",\"s\":\"Scientists used pyrolysis to break down plastic waste into useful fuel.\",\"p\":\"py-ROL-ih-sis\",\"o\":\"Greek\",\"y\":7,\"bp\":34,\"m\":\"pyrolisis\",\"sy\":\"py.rol.y.sis\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyrolytic\",\"d\":\"resulting from pyrolysis\",\"s\":\"The pyrolytic coating on the oven walls allows it to self-clean at extremely high temperatures.\",\"p\":\"py-roh-LIT-ik\",\"o\":\"Latin\",\"y\":8,\"bp\":34,\"m\":\"pyrolitic\",\"sy\":\"py.ro.lyt.ic\",\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"olatin\"]},{\"w\":\"pyromancy\",\"d\":\"divination by fire or flames\",\"s\":\"The ancient oracle practiced pyromancy, reading futures in the dancing flames of a torch.\",\"p\":\"PY-roh-man-see\",\"o\":\"Greek\",\"y\":9,\"bp\":34,\"sy\":\"py.ro.man.cy\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyromania\",\"d\":\"an uncontrollable desire to set fire to things\",\"s\":\"The detective suspected that pyromania was behind the string of mysterious warehouse fires.\",\"p\":\"py-roh-MAY-nee-uh\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"m\":\"pyromanea\",\"sy\":\"py.ro.ma.ni.a\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"pyrometer\",\"d\":\"a thermometer designed to measure high temperatures\",\"s\":\"The steelworker used a pyrometer to measure the temperature of the molten metal in the furnace.\",\"p\":\"py-ROM-ih-ter\",\"o\":\"Greek\",\"y\":8,\"bp\":34,\"m\":\"pyromoter\",\"sy\":\"py.rom.e.ter\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"tools\",\"numbers\",\"ogreek\"]},{\"w\":\"pyropes\",\"d\":\"a deep red garnet used as a gemstone\",\"s\":\"The jeweler displayed a bracelet studded with brilliant red pyropes that glittered under the light.\",\"p\":\"PY-rohps\",\"o\":\"Greek\",\"y\":9,\"bp\":30,\"m\":\"pyrops\",\"sy\":\"py.ropes\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"minerals\",\"ogreek\"]},{\"w\":\"pyroscope\",\"d\":\"a pyrometer that uses the color of the light emitted by a hot object\",\"s\":\"Engineers aimed the pyroscope at the glowing furnace to determine its precise temperature.\",\"p\":\"PY-roh-skohp\",\"o\":\"Greek\",\"y\":9,\"bp\":33,\"m\":\"pyrascope\",\"sy\":\"py.ro.scope\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"colors\",\"ogreek\"]},{\"w\":\"pyrosis\",\"d\":\"a painful burning sensation in the chest caused by gastroesophageal reflux (backflow from the stomach irritating the esophagus); symptomatic of an ulcer or a diaphragmatic hernia or other disorder\",\"s\":\"After eating too much spicy food, he suffered from pyrosis that kept him up all night.\",\"p\":\"py-ROH-sis\",\"o\":\"Greek\",\"y\":9,\"bp\":31,\"m\":\"pyrocis\",\"sy\":\"py.ro.sis\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"ogreek\"]},{\"w\":\"pyrosises\",\"d\":\"a painful burning sensation in the chest caused by gastroesophageal reflux (backflow from the stomach irritating the esophagus); symptomatic of an ulcer or a diaphragmatic hernia or other disorder\",\"s\":\"Repeated pyrosises after meals finally convinced her to visit the doctor about her diet.\",\"p\":\"py-ROH-sis-ez\",\"o\":\"Greek\",\"y\":9,\"bp\":34,\"m\":\"pyrocises\",\"sy\":\"py.ro.sis.es\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"ogreek\"]},{\"w\":\"pyrostat\",\"d\":\"a thermostat that operates at very high temperatures\",\"s\":\"The industrial kiln relied on a pyrostat to maintain the precise temperature needed for firing ceramics.\",\"p\":\"PY-roh-stat\",\"o\":\"Greek\",\"y\":9,\"bp\":32,\"m\":\"pirostat\",\"sy\":\"py.ro.stat\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyrostats\",\"d\":\"a thermostat that operates at very high temperatures\",\"s\":\"Several pyrostats were installed throughout the smelting plant to monitor extreme heat levels.\",\"p\":\"PY-roh-stats\",\"o\":\"Greek\",\"y\":9,\"bp\":33,\"m\":\"pirostats\",\"sy\":\"py.ro.stats\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyroxenes\",\"d\":\"any of a group of crystalline silicate mineral common in igneous and metamorphic rocks\",\"s\":\"The geology student identified pyroxenes in the rock sample by their dark green crystal structure.\",\"p\":\"PY-rok-seenz\",\"o\":\"Greek\",\"y\":8,\"bp\":33,\"m\":\"pyroxines\",\"sy\":\"py.rox.enes\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"minerals\",\"ogreek\"]},{\"w\":\"pyroxylin\",\"d\":\"highly flammable nitrocellulose used in making collodion and plastics and lacquers\",\"s\":\"Early photographers used pyroxylin to create the sticky coating needed on glass plate negatives.\",\"p\":\"py-ROK-sih-lin\",\"o\":\"Greek\",\"y\":9,\"bp\":34,\"m\":\"pyroxilin\",\"sy\":\"py.rox.y.lin\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyrrhics\",\"d\":\"a metrical unit with unstressed-unstressed syllables\",\"s\":\"The poetry professor pointed out several pyrrhics in the verse that gave the poem a rushing, light rhythm.\",\"p\":\"PIR-iks\",\"o\":\"Greek\",\"y\":9,\"bp\":30,\"m\":\"pirhics\",\"sy\":\"pyr.rhics\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"wordwords\",\"ogreek\"]},{\"w\":\"pyrrhus\",\"d\":\"king of Epirus; defeated the Romans in two battles in spite of staggering losses (319-272 BC)\",\"s\":\"Pyrrhus won the battle but lost so many soldiers that his victory offered little comfort.\",\"p\":\"PIR-us\",\"o\":\"Greek\",\"y\":8,\"bp\":30,\"m\":\"pyrus\",\"sy\":\"pyr.rhus\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"war\",\"ancient\",\"royalty\",\"ogreek\"]},{\"w\":\"pyrularia\",\"d\":\"small genus of chiefly Asiatic parasitic shrubs\",\"s\":\"Botanists studying parasitic plants in Asia discovered a new variety of pyrularia clinging to the roots of nearby trees.\",\"p\":\"pir-yoo-LAIR-ee-uh\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"m\":\"pyrularea\",\"sy\":\"pyr.u.la.ri.a\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"botany\",\"olatin\"]},{\"w\":\"pythias\",\"d\":\"friend of Damon; Phintias (according to legend) was condemned to death by Dionysius the Elder and asked a respite to put his affairs in order; Damon pledged his life for the return of his friend; when Phintias returned in time the tyrant released them both (4th century BC)\",\"s\":\"The story of Damon and Pythias has been retold for centuries as the ultimate example of loyal friendship.\",\"p\":\"PITH-ee-us\",\"o\":\"Greek\",\"y\":7,\"bp\":31,\"m\":\"pytheas\",\"sy\":\"pyth.i.as\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"myth\",\"time\",\"ogreek\"]},{\"w\":\"pythium\",\"d\":\"A group of fungi that cause young plants to rot at the base.\",\"s\":\"The gardener discovered that pythium was causing the seedlings to rot at the base of their stems.\",\"p\":\"PITH-ee-um\",\"o\":\"Greek\",\"y\":7,\"bp\":31,\"m\":\"pytheum\",\"sy\":\"pyth.i.um\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"botany\",\"ogreek\"]},{\"w\":\"pythius\",\"d\":\"epithet for Apollo; from the dragon Python which he killed\",\"s\":\"Worshippers at Delphi honored Apollo as Pythius, the slayer of the great serpent Python.\",\"p\":\"PITH-ee-us\",\"o\":\"Greek\",\"y\":9,\"bp\":31,\"m\":\"pytheous\",\"sy\":\"pyth.i.us\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"myth\",\"ogreek\"]},{\"w\":\"pythoness\",\"d\":\"a witch with powers of divination\",\"s\":\"The villagers feared the old pythoness who claimed to see the future in her smoky crystal bowl.\",\"p\":\"PY-thon-es\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"m\":\"pythoness spelled pythonness\",\"sy\":\"py.thon.ess\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"pythons\",\"d\":\"large Old World boas\",\"s\":\"The wildlife documentary showed pythons slowly coiling around their prey in the dense jungle undergrowth.\",\"p\":\"PY-thonz\",\"o\":\"Greek\",\"y\":6,\"bp\":30,\"m\":\"phythons\",\"sy\":\"py.thons\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyurias\",\"d\":\"presence of white blood cells in the urine; symptom of urinary tract infection\",\"s\":\"The lab technician noted that recurring pyurias in the patient strongly suggested a chronic kidney infection.\",\"p\":\"py-YOO-ree-uz\",\"o\":\"Greek\",\"y\":8,\"bp\":33,\"m\":\"pyureas\",\"sy\":\"py.u.ri.as\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"ogreek\"]},{\"w\":\"pyxides\",\"d\":\"fruit of such plants as the plantain; a capsule whose upper part falls off when the seeds are released\",\"s\":\"The botany class examined pyxides under the microscope to see how the top detaches when seeds are ready to disperse.\",\"p\":\"PIK-sih-deez\",\"o\":\"Greek\",\"y\":8,\"bp\":31,\"m\":\"pyxids\",\"sy\":\"pyx.i.des\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"botany\",\"ogreek\"]},{\"w\":\"pyxidia\",\"d\":\"fruit of such plants as the plantain; a capsule whose upper part falls off when the seeds are released\",\"s\":\"The professor collected dried pyxidia from the garden to demonstrate how the seed capsules open.\",\"p\":\"pik-SID-ee-uh\",\"o\":\"Greek\",\"y\":9,\"bp\":33,\"m\":\"pyxidea\",\"sy\":\"pyx.id.i.a\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"botany\",\"ogreek\"]},{\"w\":\"pyxidium\",\"d\":\"fruit of such plants as the plantain; a capsule whose upper part falls off when the seeds are released\",\"s\":\"Each pyxidium on the plantain plant neatly splits open at the top to release its seeds.\",\"p\":\"pik-SID-ee-um\",\"o\":\"Greek\",\"y\":8,\"bp\":33,\"m\":\"pyxideum\",\"sy\":\"pyx.id.i.um\",\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"botany\",\"ogreek\"]},{\"w\":\"pâtissier\",\"d\":\"A professional chef who specializes in making fine pastries, cakes, and tarts.\",\"o\":\"French\",\"y\":7,\"bp\":30,\"m\":\"patissier\",\"nt\":\"Open\",\"t\":[\"culinary\",\"dishes\",\"festivals\",\"ofrench\"]},{\"w\":\"pylonlike\",\"d\":\"Resembling a pylon in form or function, describing something that is tall, tapering, and gateway-like in its structure or appearance.\",\"s\":\"The massive stone pillars at the entrance of the ancient Egyptian temple were described as pylonlike in their grandeur.\",\"p\":\"PY-lon-lyk\",\"o\":\"Greek\",\"y\":9,\"bp\":28,\"sy\":\"py.lon.like\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"pyothorax\",\"d\":\"A medical condition in which pus accumulates in the pleural cavity of the chest, usually caused by a bacterial infection, also known as empyema.\",\"s\":\"The doctor diagnosed the patient with pyothorax after discovering a dangerous accumulation of pus in the chest cavity.\",\"p\":\"py-oh-THOR-aks\",\"o\":\"Greek\",\"y\":8,\"bp\":26,\"sy\":\"pyotho.rax\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"ogreek\"]},{\"w\":\"pyramidoid\",\"d\":\"Having a shape resembling a pyramid, with a broad base that narrows to a point or apex at the top.\",\"s\":\"The architect designed a pyramidoid structure for the new museum, giving it a sleek, tapering silhouette.\",\"p\":\"pih-RAM-ih-doyd\",\"o\":\"Greek\",\"y\":9,\"bp\":29,\"sy\":\"pyra.mi.doid\",\"ps\":\"adjective\",\"t\":[\"ancient\",\"ogreek\"]},{\"w\":\"pyrenoid\",\"d\":\"A small, dense protein body found in the chloroplasts of algae and some other simple plants, serving as a center for carbon fixation during photosynthesis.\",\"s\":\"Under the microscope, the student could see the pyrenoid inside the algae cell, where starch was being produced.\",\"p\":\"PY-ruh-noyd\",\"o\":\"Greek\",\"y\":9,\"bp\":24,\"ps\":\"noun\",\"t\":[\"botany\",\"chemistry\",\"ogreek\"]},{\"w\":\"pyrenous\",\"d\":\"Having or containing a hard central kernel or stone, as in fruits that have a pit or seed surrounded by pulpy flesh.\",\"s\":\"The botanist described the berry as pyrenous because it contained a hard stone or kernel at its center.\",\"p\":\"PY-ruh-nus\",\"o\":\"Greek\",\"y\":9,\"bp\":25,\"sy\":\"pyre.nous\",\"ps\":\"adjective\",\"t\":[\"botany\",\"minerals\",\"spices\",\"ogreek\"]},{\"w\":\"pyroclast\",\"d\":\"A fragment of rock or lava that is violently ejected from a volcano during an eruption, ranging in size from fine ash particles to large boulders.\",\"s\":\"Each pyroclast ejected by the erupting volcano was a fragment of rock hurled high into the sky.\",\"p\":\"PY-roh-klast\",\"o\":\"Greek\",\"y\":9,\"bp\":28,\"sy\":\"py.ro.clast\",\"ps\":\"noun\",\"t\":[\"minerals\",\"physics\",\"landforms\",\"ogreek\"]},{\"w\":\"pyrokinesis\",\"d\":\"The supposed psychic or supernatural ability to create, control, or manipulate fire using only the power of one's mind, a concept popular in science fiction.\",\"s\":\"In the fantasy novel, the villain used pyrokinesis to start fires with nothing more than a focused thought.\",\"p\":\"py-roh-kih-NEE-sis\",\"o\":\"Greek\",\"y\":8,\"bp\":37,\"sy\":\"py.roki.ne.sis\",\"ps\":\"noun\",\"t\":[\"ogreek\"]},{\"w\":\"pyrophone\",\"d\":\"A musical instrument that produces sound through the vibration of flames inside glass tubes, creating an eerie, organ-like tone powered entirely by fire.\",\"s\":\"The inventor demonstrated the pyrophone at the science fair, producing eerie musical tones using jets of flame.\",\"p\":\"PY-roh-fohn\",\"o\":\"Greek\",\"y\":9,\"bp\":28,\"sy\":\"py.ro.phone\",\"ps\":\"noun\",\"t\":[\"music\",\"ogreek\"]},{\"w\":\"pysma\",\"d\":\"A rhetorical figure in which a speaker asks a rapid series of questions in succession, each building on the last, to create emphasis or overwhelm a listener.\",\"s\":\"The rhetoric teacher introduced pysma as a technique where a speaker asks many rapid questions to overwhelm the audience.\",\"p\":\"PIZ-muh\",\"o\":\"Greek\",\"y\":9,\"bp\":17,\"sy\":\"pys.ma\",\"ps\":\"noun\",\"t\":[\"buildings\",\"ogreek\"]},{\"w\":\"pythiad\",\"d\":\"A four-year period or cycle between the Pythian Games held at Delphi in ancient Greece, used as a unit of time in classical Greek chronology.\",\"s\":\"Scholars recorded that the famous oracle at Delphi gave her most celebrated prophecy during a celebrated pythiad.\",\"p\":\"PITH-ee-ad\",\"o\":\"Greek\",\"y\":9,\"bp\":19,\"sy\":\"pythi.ad\",\"ps\":\"noun\",\"t\":[\"ancient\",\"sports\",\"numbers\",\"time\",\"ogreek\"]},{\"w\":\"pythonlike\",\"d\":\"Resembling a python in character or appearance, especially describing something that is large, slow-moving, powerfully constricting, or sinuously coiled.\",\"s\":\"The thick pythonlike cables coiled around the old machinery made the factory floor look almost alive.\",\"p\":\"PY-thun-lyk\",\"o\":\"Greek\",\"y\":9,\"bp\":27,\"sy\":\"python.like\",\"ps\":\"adjective\",\"t\":[\"ogreek\"]},{\"w\":\"Pynchonesque\",\"d\":\"Resembling or characteristic of the writing style of American novelist Thomas Pynchon, typically involving complex, labyrinthine plots, dark humor, paranoia, and an overwhelming sense of conspiracy and entropy.\",\"s\":\"The student's short story was delightfully Pynchonesque, weaving together secret government agencies, bizarre coincidences, and unreliable narrators into a dizzyingly complex web of paranoid intrigue.\",\"p\":\"PIN-chun-esk\",\"o\":\"French\",\"y\":9,\"bp\":35,\"sy\":\"pyn.chonesque\",\"ps\":\"adjective\",\"t\":[\"ofrench\"]},{\"w\":\"pyodermic\",\"d\":\"Relating to or characterized by a skin infection that produces pus; of or pertaining to a bacterial skin condition involving pustules or purulent sores.\",\"s\":\"The dermatologist identified the child's rash as a pyodermic infection caused by bacteria, and immediately prescribed antibiotics to clear the spreading clusters of pus-filled sores.\",\"p\":\"peye-oh-DUR-mik\",\"o\":\"French\",\"y\":8,\"bp\":29,\"sy\":\"py.o.der.mic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"character\",\"ofrench\"]},{\"w\":\"pyorrheic\",\"d\":\"Relating to or characterized by pyorrhea, a condition involving the discharge of pus, especially from the gums and tooth sockets in periodontal disease.\",\"s\":\"The dentist noted the patient's pyorrheic gums during the examination, explaining that the persistent bacterial infection had caused significant tissue damage and would require immediate and aggressive treatment.\",\"p\":\"peye-oh-REE-ik\",\"o\":\"French\",\"y\":9,\"bp\":29,\"sy\":\"py.or.rhe.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"character\",\"ofrench\"]},{\"w\":\"pyorrhoeic\",\"d\":\"The British spelling variant of pyorrheic; relating to or characterized by the discharge of pus from the gums or tooth sockets, as in periodontal disease.\",\"s\":\"The British dental journal published a study on pyorrhoeic conditions in elderly patients, recommending stricter oral hygiene protocols to prevent the bacterial infections that cause such painful gum deterioration.\",\"p\":\"peye-oh-REE-ik\",\"o\":\"French\",\"y\":9,\"bp\":30,\"sy\":\"py.or.rhoe.ic\",\"ps\":\"adjective\",\"t\":[\"body\",\"disease\",\"character\",\"wordwords\",\"ofrench\"]},{\"w\":\"pyramidism\",\"d\":\"The practice, belief, or doctrine associated with pyramids, including theories about the mystical or supernatural powers of pyramid shapes, or the historical and cultural study of pyramid structures.\",\"s\":\"The professor dismissed pyramidism as pseudoscience, patiently explaining that no credible evidence supports the idea that pyramid shapes preserve food, sharpen blades, or channel cosmic energy.\",\"p\":\"PIR-uh-mid-iz-um\",\"o\":\"French\",\"y\":9,\"bp\":27,\"sy\":\"pyra.midism\",\"ps\":\"noun\",\"t\":[\"ancient\",\"logic\",\"ofrench\"]},{\"w\":\"pyramidlike\",\"d\":\"Resembling a pyramid in shape, structure, or form; having the characteristic triangular sides and pointed apex of a pyramid.\",\"s\":\"The architect designed a pyramidlike glass atrium for the museum entrance, its four triangular glass panels rising to a sharp peak that flooded the lobby below with natural light.\",\"p\":\"PIR-uh-mid-leyek\",\"o\":\"French\",\"y\":9,\"bp\":35,\"sy\":\"pyra.mid.like\",\"ps\":\"adjective\",\"t\":[\"ancient\",\"ofrench\"]},{\"w\":\"pyroacid\",\"d\":\"An acid derived by the removal of water from another acid through the application of heat, or an acid produced by or associated with fire and high-temperature chemical reactions.\",\"s\":\"The chemistry textbook explained that a pyroacid is typically formed when gentle heating drives off water molecules from a standard acid, producing a more concentrated and reactive compound.\",\"p\":\"peye-roh-AS-id\",\"o\":\"French\",\"y\":9,\"bp\":19,\"sy\":\"py.roacid\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"ofrench\"]},{\"w\":\"pyrochloric\",\"d\":\"Relating to or designating hydrochloric acid produced or modified by heat, or pertaining to chemical reactions involving chlorine compounds under high-temperature or fire conditions.\",\"s\":\"The industrial chemist carefully documented the pyrochloric reaction that occurred when the chlorinated compound was exposed to extreme heat, producing a dangerously corrosive gas as a byproduct.\",\"p\":\"peye-roh-KLOR-ik\",\"o\":\"French\",\"y\":9,\"bp\":35,\"sy\":\"py.rochlo.ric\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"ofrench\"]},{\"w\":\"pycnonuclear\",\"d\":\"Relating to nuclear reactions that occur under conditions of extremely high density, such as those found in the cores of white dwarf stars.\",\"s\":\"Researchers studying pycnonuclear reactions must account for the extreme density conditions found in white dwarf stars.\",\"p\":\"pik-noh-NOO-klee-er\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"py.c.nonu.cle.ar\",\"ps\":\"adjective\",\"t\":[\"astronomy\",\"olatin\"]},{\"w\":\"pygidium\",\"d\":\"The posterior body section or tail shield of certain invertebrates such as trilobites and some insects, forming the rearmost segment of the body.\",\"s\":\"The fossil trilobite had a well-preserved pygidium, the shield-like tail section clearly visible under the microscope.\",\"p\":\"py-JID-ee-um\",\"o\":\"Latin\",\"y\":7,\"bp\":28,\"sy\":\"py.gid.i.um\",\"ps\":\"noun\",\"t\":[\"insects\",\"war\",\"olatin\"]},{\"w\":\"pykrete\",\"d\":\"A composite material made of water ice mixed with wood pulp or sawdust, which is significantly stronger and slower to melt than pure ice.\",\"s\":\"During World War II, scientists proposed building aircraft carriers out of pykrete, a mixture of ice and sawdust.\",\"p\":\"PY-kreet\",\"o\":\"Latin\",\"y\":9,\"bp\":17,\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"pyral\",\"d\":\"Of or relating to a pyre or funeral fire; pertaining to the burning or combustion associated with ceremonial or ritual fire.\",\"s\":\"The ancient ceremony included a pyral ritual in which offerings were cast into a sacred bonfire.\",\"p\":\"PY-rul\",\"o\":\"Latin\",\"y\":8,\"bp\":16,\"ps\":\"adjective\",\"t\":[\"chemistry\",\"religion\",\"olatin\"]},{\"w\":\"Pyrenean\",\"d\":\"Of or relating to the Pyrenees, the mountain range forming the border between France and Spain, or to the people and culture of that region.\",\"s\":\"The hikers marveled at the Pyrenean landscape as they crossed the mountain range between France and Spain.\",\"p\":\"peer-uh-NEE-un\",\"o\":\"Latin\",\"y\":7,\"bp\":25,\"sy\":\"pyre.nean\",\"ps\":\"adjective\",\"t\":[\"landforms\",\"olatin\"]},{\"w\":\"pyridinium\",\"d\":\"A positively charged ion derived from pyridine by the addition of a proton or alkyl group, commonly found in many biological and chemical compounds.\",\"s\":\"The chemistry student learned that pyridinium ions form when pyridine accepts a proton in an acid reaction.\",\"p\":\"peer-ih-DIN-ee-um\",\"o\":\"Latin\",\"y\":8,\"bp\":29,\"sy\":\"pyri.dini.um\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"physics\",\"numbers\",\"olatin\"]},{\"w\":\"pyriform\",\"d\":\"Having a shape resembling that of a pear; tapering from a rounded base to a narrower top, used in anatomy and biology to describe pear-shaped structures.\",\"s\":\"The botanist described the fruit as pyriform, noting its distinct pear-shaped appearance.\",\"p\":\"PEER-ih-form\",\"o\":\"Latin\",\"y\":7,\"bp\":25,\"sy\":\"pyri.form\",\"ps\":\"adjective\",\"t\":[\"body\",\"spices\",\"olatin\"]},{\"w\":\"pyroclastic\",\"d\":\"Relating to fragments of rock, ash, and lava violently ejected during a volcanic eruption and carried through the air.\",\"s\":\"The pyroclastic flow from the erupting volcano raced down the mountainside, destroying everything in its path.\",\"p\":\"PEYE-roh-KLAS-tik\",\"o\":\"Latin\",\"y\":7,\"bp\":37,\"sy\":\"py.ro.clas.tic\",\"ps\":\"adjective\",\"t\":[\"minerals\",\"olatin\"]},{\"w\":\"pyroelectrodynamic\",\"d\":\"Relating to the movement or flow of electrically charged particles or currents generated by the application of heat or fire.\",\"s\":\"The engineering team investigated pyroelectrodynamic principles to develop new ways of generating electricity from heat.\",\"p\":\"PEYE-roh-ih-lek-troh-deye-NAM-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"py.ro.elec.tro.dy.nam.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"pyroelectrodynamics\",\"d\":\"The branch of science that studies the generation and behavior of electric currents and charged-particle motion caused by heat or fire.\",\"s\":\"The textbook devoted an entire chapter to pyroelectrodynamics, explaining how thermal energy can produce electrical movement.\",\"p\":\"PEYE-roh-ih-lek-troh-deye-NAM-iks\",\"o\":\"Latin\",\"y\":9,\"bp\":33,\"sy\":\"py.ro.elec.tro.dy.nam.ics\",\"ps\":\"noun\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"pyrogeography\",\"d\":\"The study of the geographic distribution and patterns of wildfires and fire-related phenomena across Earth's landscapes and regions.\",\"s\":\"Experts in pyrogeography study how wildfires spread across different landscapes and climates around the world.\",\"p\":\"PEYE-roh-jee-OG-ruh-fee\",\"o\":\"Latin\",\"y\":9,\"bp\":28,\"sy\":\"py.ro.geog.ra.phy\",\"ps\":\"noun\",\"t\":[\"olatin\"]},{\"w\":\"pyroglutamic\",\"d\":\"A ring-shaped acid made by heating a common protein amino acid until it forms a loop.\",\"s\":\"The biochemist identified pyroglutamic acid as a key component in certain proteins and antioxidant compounds.\",\"p\":\"PEYE-roh-gloo-TAM-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"py.rog.lu.tam.ic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"pyrography\",\"d\":\"the act of producing drawings on wood or leather by using heated tools or a fine flame\",\"s\":\"She used pyrography to burn an intricate design of flowers into a smooth wooden jewelry box.\",\"p\":\"peye-ROG-ruh-fee\",\"o\":\"Latin\",\"y\":8,\"bp\":30,\"sy\":\"py.rog.ra.phy\",\"ps\":\"noun\",\"t\":[\"painting\",\"tools\",\"olatin\"]},{\"w\":\"pyromagnetic\",\"d\":\"Relating to the relationship between heat or fire and magnetic properties, especially the changes in a material's magnetism caused by temperature.\",\"s\":\"The scientist studied pyromagnetic effects to understand how heat changes a material's magnetic properties.\",\"p\":\"PEYE-roh-mag-NET-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":39,\"sy\":\"py.ro.mag.net.ic\",\"ps\":\"adjective\",\"t\":[\"physics\",\"olatin\"]},{\"w\":\"pyromellitic\",\"d\":\"relating to an acid used to make heat-resistant plastics and resins\",\"s\":\"Pyromellitic dianhydride is an important chemical used in the production of high-performance plastics.\",\"p\":\"PEYE-roh-meh-LIT-ik\",\"o\":\"Latin\",\"y\":9,\"bp\":36,\"sy\":\"py.romel.litic\",\"ps\":\"adjective\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"pyrone\",\"d\":\"An organic chemical compound containing a six-membered ring with one oxygen atom and one ketone group, occurring in two structural forms and found in various natural substances.\",\"s\":\"The organic chemistry class learned that pyrone is a six-membered ring compound containing both oxygen and a carbonyl group.\",\"p\":\"PEYE-rohn\",\"o\":\"Latin\",\"y\":9,\"bp\":18,\"sy\":\"py.rone\",\"ps\":\"noun\",\"t\":[\"chemistry\",\"olatin\"]},{\"w\":\"pyrophobia\",\"d\":\"a morbid fear of fire\",\"s\":\"His pyrophobia was so intense that he refused to attend any barbecue or bonfire event.\",\"p\":\"PEYE-roh-FOH-bee-uh\",\"o\":\"Latin\",\"y\":9,\"bp\":30,\"sy\":\"py.ro.pho.bia\",\"ps\":\"noun\",\"t\":[\"emotions\",\"olatin\"]},{\"w\":\"pyrosphere\",\"d\":\"The extremely hot, molten layer deep within the Earth's interior, essentially the liquid and semi-liquid zone of the planet where rock melts due to intense heat.\",\"s\":\"Geologists sometimes use the term pyrosphere to describe the intensely hot molten layer deep within the Earth.\",\"p\":\"PEYE-roh-sfeer\",\"o\":\"Latin\",\"y\":9,\"bp\":29,\"sy\":\"py.ro.sphere\",\"ps\":\"noun\",\"t\":[\"astronomy\",\"minerals\",\"olatin\"]},{\"w\":\"pyrotechnical\",\"d\":\"of or relating to the craft of making fireworks\",\"s\":\"The pyrotechnical crew worked carefully through the night to set up a spectacular display of colorful rockets and glittering starbursts that would light up the entire harbor skyline.\",\"p\":\"PEYE-roh-TEK-nih-kul\",\"o\":\"Latin\",\"y\":9,\"bp\":26,\"sy\":\"py.rotech.ni.cal\",\"ps\":\"adjective\",\"t\":[\"festivals\",\"olatin\"]},{\"w\":\"pyrotherapy\",\"d\":\"A medical treatment that uses the application of heat or artificially induced fever to fight disease or promote healing in the body.\",\"s\":\"Early doctors experimented with pyrotherapy, deliberately raising a patient's body temperature to fight certain infections.\",\"p\":\"PEYE-roh-THAIR-uh-pee\",\"o\":\"Latin\",\"y\":9,\"bp\":37,\"sy\":\"py.rother.a.py\",\"ps\":\"noun\",\"t\":[\"body\",\"disease\",\"olatin\"]},{\"w\":\"Pythagoreanism\",\"d\":\"The philosophical and mathematical belief system founded by the ancient Greek thinker Pythagoras, emphasizing that numbers are the fundamental principles of the universe and that the soul is immortal and undergoes reincarnation.\",\"s\":\"Students of Pythagoreanism believe that numbers are the foundation of all reality and the universe's order.\",\"p\":\"pih-thag-uh-REE-uh-niz-um\",\"o\":\"Latin\",\"y\":9,\"bp\":24,\"sy\":\"pythagore.anism\",\"ps\":\"noun\",\"t\":[\"astronomy\",\"ancient\",\"logic\",\"numbers\",\"olatin\"]},{\"w\":\"Pythian\",\"d\":\"Relating to the ancient Greek oracle at Delphi, to the god Apollo, or the games held there.\",\"s\":\"The ancient oracle at Delphi was known as the Pythian priestess, believed to speak the words of Apollo.\",\"p\":\"PITH-ee-un\",\"o\":\"Latin\",\"y\":7,\"bp\":19,\"sy\":\"pythi.an\",\"ps\":\"adjective\",\"t\":[\"myth\",\"religion\",\"ancient\",\"sports\",\"olatin\"]},{\"w\":\"pyrrolidone\",\"d\":\"a nitrogen-containing organic compound used as a solvent and in making medicines\",\"y\":9,\"bp\":54,\"nt\":\"Senior\",\"t\":[\"pharmacy\",\"chemistry\",\"buildings\",\"body\"]},{\"w\":\"pyrrhonism\",\"d\":\"the philosophy of suspending judgement about everything\",\"s\":\"His pyrrhonism made him doubt even his own doubts.\",\"p\":\"PIH-ruh-nih-zuhm\",\"y\":9,\"bp\":4,\"m\":\"pyrhonism\",\"nt\":\"Advanced | North South Finals\",\"ps\":\"noun\",\"sy\":\"pyr.rho.nism\",\"o\":\"Greek\",\"t\":[\"logic\",\"philosophy\",\"eponyms\",\"ogreek\",\"epgreek\"]}]",h:"[{\"w\":\"pycnocline\",\"d\":\"A layer of water in a lake or sea where the density changes rapidly with depth.\",\"s\":\"The submarine smoothly descended past the pycnocline to reach the denser, colder waters below.\",\"p\":\"PIK-nuh-kline\",\"o\":\"Greek\",\"y\":9,\"bp\":50,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"ocean\",\"physics\",\"waterways\",\"ogreek\"],\"m\":\"picnocline\",\"sy\":\"pyc.no.cline\"},{\"w\":\"pyrgeometer\",\"d\":\"An instrument that measures the invisible thermal radiation traveling downward from the sky.\",\"s\":\"The observatory uses a pyrgeometer at night to measure how much heat is radiating back down from above.\",\"p\":\"pur-jee-OM-uh-ter\",\"o\":\"Greek\",\"y\":9,\"bp\":55,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"meteorology\",\"instruments\",\"physics\",\"music\",\"numbers\",\"ogreek\"],\"m\":\"pyrgeometor\",\"sy\":\"pyr.ge.om.e.ter\"},{\"w\":\"pyrheliometer\",\"d\":\"A device that strictly measures the direct beam of sunlight coming straight from the sun.\",\"s\":\"To make sure their solar panels would work efficiently, the engineers tested the location's sunlight with a pyrheliometer.\",\"p\":\"pur-hee-lee-OM-uh-ter\",\"o\":\"Greek\",\"y\":9,\"bp\":60,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"meteorology\",\"instruments\",\"astronomy\",\"tools\",\"numbers\",\"ogreek\"],\"m\":\"pyrheliometre\",\"sy\":\"pyr.he.li.om.e.ter\"},{\"w\":\"pyranometer\",\"d\":\"An instrument that measures all the solar radiation hitting a flat surface from the entire hemisphere of the sky.\",\"s\":\"The weather station's rooftop pyranometer recorded how much total sunlight brightened the cloudy afternoon.\",\"p\":\"py-ruh-NOM-uh-ter\",\"o\":\"Greek\",\"y\":9,\"bp\":55,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"meteorology\",\"instruments\",\"astronomy\",\"physics\",\"maps\",\"music\",\"numbers\",\"ogreek\"],\"m\":\"pyranomiter\",\"sy\":\"py.ran.om.e.ter\"},{\"w\":\"pyrheliometry\",\"d\":\"The measurement of the heating power of the sun's direct radiation.\",\"s\":\"In order to design better solar panels, the researchers used pyrheliometry to measure how much energy the midday sunshine contained.\",\"p\":\"py-ree-lee-OM-uh-tree\",\"o\":\"Greek\",\"y\":9,\"bp\":60,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"science\",\"measurement\",\"astronomy\",\"physics\",\"numbers\",\"ogreek\"],\"m\":\"pyreliometry\",\"sy\":\"pyr.he.li.om.e.try\"},{\"w\":\"pygostyle\",\"d\":\"The tailbone of a bird, formed by several fused bones, which supports the tail feathers.\",\"s\":\"The majestic peacock uses the strong muscles attached to its pygostyle to lift its heavy, colorful tail feathers into a grand fan.\",\"p\":\"PY-guh-styl\",\"o\":\"Greek\",\"y\":9,\"bp\":45,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"bones\",\"anatomy\",\"body\",\"birds\",\"ogreek\"],\"m\":\"pygostile\",\"sy\":\"py.go.style\"},{\"w\":\"pyrargyrite\",\"d\":\"a dark red mineral containing silver that is often called dark ruby silver.\",\"s\":\"The old silver mine was famous for producing stunning crimson crystals of pyrargyrite.\",\"p\":\"py-RAHR-juh-ryt\",\"o\":\"Greek\",\"y\":9,\"bp\":60,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"mineralogy\",\"geology\",\"minerals\",\"colors\",\"ogreek\"],\"m\":\"pyragyrite\",\"sy\":\"pyr.ar.gy.rite\"},{\"w\":\"pyrometallurgy\",\"d\":\"The traditional process of using extremely high heat and fire to separate raw elements from their ores.\",\"s\":\"Most ancient civilizations used pyrometallurgy, building huge, hot fires to melt iron out of the heavy stones.\",\"p\":\"py-ro-MET-ul-er-jee\",\"o\":\"Greek\",\"y\":9,\"bp\":60,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"metallurgy\",\"history\",\"minerals\",\"festivals\",\"ogreek\"],\"m\":\"pyrometalurgy\",\"sy\":\"py.ro.met.al.lur.gy\"},{\"w\":\"pyrolusite\",\"d\":\"a soft, black mineral that is the most important ore of manganese\",\"s\":\"The dark streaks on the desert stones were deposits of pyrolusite left by ancient water.\",\"p\":\"py-roh-LOO-site\",\"o\":\"Greek\",\"y\":9,\"bp\":30,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"mineralogy\",\"mining\",\"minerals\",\"ogreek\"],\"m\":\"pyrolusight\",\"sy\":\"py.ro.lu.site\"},{\"w\":\"pycnometer\",\"d\":\"A small glass bottle with a special stopper, used to figure out the exact density of a liquid.\",\"s\":\"The chemist filled the pycnometer with oil to compare its weight with the same amount of water.\",\"p\":\"pik-NOM-ih-ter\",\"o\":\"Greek\",\"y\":9,\"bp\":50,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"instruments\",\"chemistry\",\"ogreek\"],\"m\":\"picnometer\",\"sy\":\"pyc.nom.e.ter\"},{\"w\":\"pyromorphite\",\"d\":\"A bright green or yellowish mineral composed of lead phosphate, known for melting into a glowing globule when heated.\",\"s\":\"The collector proudly displayed a cluster of barrel-shaped pyromorphite crystals under bright lights.\",\"p\":\"py-roh-MOR-fyt\",\"o\":\"Greek\",\"y\":9,\"bp\":50,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"geology\",\"minerals\",\"chemistry\",\"colors\",\"ogreek\"],\"m\":\"piromorphite\",\"sy\":\"py.ro.mor.phite\"},{\"w\":\"pyroligneous\",\"d\":\"Got by heating wood in a closed vessel until it gives off a sour smoky liquid.\",\"s\":\"The charcoal burners sold pyroligneous acid to the dyers in the valley.\",\"p\":\"py-roh-LIG-nee-us\",\"o\":\"Greek\",\"y\":9,\"bp\":68,\"nt\":\"Open\",\"ps\":\"adjective\",\"t\":[\"championship\",\"old trades\",\"chemistry\",\"seafaring\",\"ogreek\"],\"m\":\"pyrolignious\",\"sy\":\"py.ro.lig.ne.ous\"},{\"w\":\"pyknosis\",\"d\":\"The shrivelling of a dying cell's control centre into a dense dark blob.\",\"s\":\"Every cell in the damaged patch showed the tight dark spot of pyknosis.\",\"p\":\"pik-NOH-sis\",\"o\":\"Greek\",\"y\":9,\"bp\":69,\"nt\":\"Open\",\"ps\":\"noun\",\"t\":[\"championship\",\"histology\",\"ogreek\"],\"m\":\"picnosis\",\"sy\":\"pyk.no.sis\"}]"};
